<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Ball Physics Playground</title>
<style>
  :root { --bg:#111; --fg:#eee; --btn:#333; --btn-h:#444; --accent:#0af; }
  * { box-sizing:border-box; }
  body {
    margin:0; min-height:100vh; background:var(--bg); color:var(--fg);
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    font-family:system-ui, sans-serif; gap:1rem; padding:1rem;
  }
  #sim {
    background:#000; border:2px solid #333; border-radius:8px;
    box-shadow:0 0 20px rgba(0,255,255,0.1);
    width:600px; height:600px; display:block;
  }
  .controls { display:flex; gap:0.5rem; flex-wrap:wrap; justify-content:center; }
  button {
    background:var(--btn); color:var(--fg); border:none; border-radius:6px;
    padding:0.6rem 1.2rem; font-size:1rem; cursor:pointer; transition:background 0.15s;
  }
  button:hover { background:var(--btn-h); }
  button:active { transform:scale(0.98); }
  #play.playing { background:#0a8; }
</style>
</head>
<body>
<canvas id="sim" width="600" height="600"></canvas>
<div class="controls">
  <button id="drop">Drop Ball</button>
  <button id="play">Play</button>
  <button id="clear">Clear</button>
</div>

<script>
(() => {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;

  const GRAVITY = 0.5;
  const RESTITUTION = 0.8;

  const balls = [];
  let running = false;
  let lastTime = 0;

  function draw() {
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = `hsl(${b.hue}, 80%, 60%)`;
      ctx.fill();
      ctx.strokeStyle = '#fff3';
      ctx.lineWidth = 1;
      ctx.stroke();
    }
  }

  function update(dt) {
    for (const b of balls) {
      b.vy += GRAVITY * dt;
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx *= -RESTITUTION;
      } else if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx *= -RESTITUTION;
      }
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy *= -RESTITUTION;
      } else if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy *= -RESTITUTION;
      }
    }
  }

  function step(dt = 1) {
    update(dt);
    draw();
  }

  function addBall(x, y, vx = 0, vy = 0, r = 20) {
    balls.push({
      x, y, vx, vy, r,
      hue: Math.random() * 360
    });
  }

  function clear() {
    balls.length = 0;
    draw();
  }

  function loop(time) {
    if (running) {
      const dt = (time - lastTime) / 16.67; // normalize to ~60fps steps
      lastTime = time;
      step(dt);
      requestAnimationFrame(loop);
    }
  }

  // Event listeners
  document.getElementById('drop').addEventListener('click', () => {
    addBall(W / 2, 50, (Math.random() - 0.5) * 4, 0, 15 + Math.random() * 20);
  });

  const playBtn = document.getElementById('play');
  playBtn.addEventListener('click', () => {
    running = !running;
    playBtn.classList.toggle('playing', running);
    playBtn.textContent = running ? 'Pause' : 'Play';
    if (running) {
      lastTime = performance.now();
      requestAnimationFrame(loop);
    }
  });

  document.getElementById('clear').addEventListener('click', clear);

  canvas.addEventListener('click', e => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    addBall(x, y, (Math.random() - 0.5) * 6, (Math.random() - 0.5) * 6, 10 + Math.random() * 25);
  });

  // Expose API
  window.sim = {
    get w() { return W; },
    get h() { return H; },
    balls: () => balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })),
    addBall,
    clear,
    step
  };

  // Initial draw
  draw();
})();
</script>
</body>
</html>
